175	static int wdt_feed_task(int argc, FAR char *argv[])
176	{
177	  uint32_t starve_log = 0;
178	  int fd;
179	
180	  (void)argc;
181	  (void)argv;
182	
183	  fd = open(WDT_DEVPATH, O_RDONLY);
184	  if (fd < 0)
185	    {
186	      syslog(LOG_ERR, "[wdt] feeder open %s failed errno=%d\n",
187	             WDT_DEVPATH, errno);
188	      return ERROR;
189	    }
190	
191	  for (; ; )
192	    {
193	      bool feed = wdt_should_feed();
194	
195	      g_feeding = feed;
196	      if (feed)
197	        {
198	          if (ioctl(fd, WDIOC_KEEPALIVE, 0) < 0)
199	            {
200	              syslog(LOG_ERR, "[wdt] KEEPALIVE errno=%d\n", errno);
201	            }
202	
203	          starve_log = 0;
204	        }
205	      else if (starve_log == 0)
206	        {
207	          syslog(LOG_ERR,
208	                 "[wdt] stop feed idle=%ums work=%ums ui=%ums "
209	                 "ui_seen=%d ui_req=%d suppress=%d\n",
210	                 (unsigned)wdt_age_ms(g_idle_beat),
211	                 g_work_seen ? (unsigned)wdt_age_ms(g_work_beat) : 0u,
212	                 g_ui_seen ? (unsigned)wdt_age_ms(g_ui_beat) : 0u,
213	                 g_ui_seen ? 1 : 0,
214	                 g_ui_required ? 1 : 0,
215	                 g_suppressed ? 1 : 0);
216	          myvendor_coredump_wdt();
217	          starve_log = 1;
218	        }
219	
220	      usleep((useconds_t)CONFIG_MYVENDOR_WATCHDOG_FEED_MS * 1000u);
221	    }
222	
223	  close(fd);
224	  return OK;
225	}
