244	void myvendor_watchdog_busy_pump(void)
245	{
246	  myvendor_watchdog_work_beat();
247	
248	  if (g_busy_yield_tick == 0)
249	    {
250	      g_busy_yield_tick = wdt_now();
251	      return;
252	    }
253	
254	  if (wdt_age_ms(g_busy_yield_tick) >= 1000u)
255	    {
256	      usleep(10000);
257	      g_busy_yield_tick = wdt_now();
258	    }
259	}
