311	int myvendor_watchdog_get_status(struct myvendor_watchdog_status_s *st)
312	{
313	  bool ui_req;
314	
315	  if (st == NULL)
316	    {
317	      return -1;
318	    }
319	
320	  ui_req = wdt_ui_required_now();
321	  st->started = g_started;
322	  st->suppressed = g_suppressed;
323	  st->feeding = g_feeding;
324	  st->idle_ok = wdt_fresh(g_idle_beat);
325	  st->work_ok = g_work_seen && wdt_fresh(g_work_beat);
326	  st->ui_seen = g_ui_seen;
327	  st->ui_required = ui_req;
328	  st->ui_ok = !ui_req || (g_ui_seen && wdt_fresh(g_ui_beat)) ||
329	              (g_work_seen && wdt_fresh(g_work_beat));
330	  st->idle_age_ms = wdt_age_ms(g_idle_beat);
331	  st->work_age_ms = g_work_seen ? wdt_age_ms(g_work_beat) : 0;
332	  st->ui_age_ms = g_ui_seen ? wdt_age_ms(g_ui_beat) : 0;
333	  st->timeout_ms = (uint32_t)CONFIG_MYVENDOR_WATCHDOG_TIMEOUT_MS;
334	  return 0;
335	}
