35	static void schedmon_copy_name(char *dst, FAR struct tcb_s *tcb)
36	{
37	  const char *n = (tcb != NULL) ? get_task_name(tcb) : "?";
38	  size_t i;
39	
40	  for (i = 0; i + 1u < MYVENDOR_SCHEDMON_NAME && n[i] != '\0'; i++)
41	    {
42	      dst[i] = n[i];
43	    }
44	
45	  dst[i] = '\0';
