48	void myvendor_schedmon_waitirq_null(FAR struct tcb_s *wtcb, int errcode)
49	{
50	  FAR struct tcb_s *rtcb = running_task();
51	  struct myvendor_schedmon_null_s *e;
52	  uint32_t n;
53	
54	  n = g_null_n + 1u;
55	  if (n == 0u)
56	    {
57	      n = 1u;
58	    }
59	
60	  g_null_n = n;
61	  e = &g_null[g_null_w];
62	  g_null_w = (uint8_t)((g_null_w + 1u) % MYVENDOR_SCHEDMON_NULL);
63	
64	  memset(e, 0, sizeof(*e));
65	  e->seq = n;
66	  e->ticks = (uint32_t)clock_systime_ticks();
67	  e->ipsr = getipsr();
68	  e->errcode = (int16_t)errcode;
69	  if (wtcb != NULL)
70	    {
71	      e->wt_pid = (int16_t)wtcb->pid;
72	      e->wt_pri = (int16_t)wtcb->sched_priority;
73	      e->wt_state = (uint8_t)wtcb->task_state;
74	      schedmon_copy_name(e->wt_name, wtcb);
75	    }
76	
77	  if (rtcb != NULL)
78	    {
79	      e->run_pid = (int16_t)rtcb->pid;
80	      e->run_lock = rtcb->lockcount;
81	      e->run_state = (uint8_t)rtcb->task_state;
82	      schedmon_copy_name(e->run_name, rtcb);
83	    }
84	
85	  memcpy(&g_snap.last_null, e, sizeof(*e));
86	  g_snap.null_n = n;
87	}
