158	static void schedmon_one(FAR struct tcb_s *tcb, FAR void *arg)
159	{
160	  struct myvendor_schedmon_snap_s *s = arg;
161	  struct myvendor_schedmon_task_s *d;
162	
163	  if (tcb == NULL || s == NULL || s->ntask >= MYVENDOR_SCHEDMON_TASKS)
164	    {
165	      return;
166	    }
167	
168	  d = &s->task[s->ntask];
169	  s->ntask++;
170	  d->pid = (int16_t)tcb->pid;
171	  d->pri = (int16_t)tcb->sched_priority;
172	  d->lockcount = tcb->lockcount;
173	  d->errcode = tcb->errcode;
174	  d->state = (uint8_t)tcb->task_state;
175	  d->waitdog = WDOG_ISACTIVE(&tcb->waitdog) ? 1u : 0u;
176	  d->waitobj = (uintptr_t)tcb->waitobj;
177	#ifdef CONFIG_STACK_COLORATION
178	  /* 栈高水位：扫染色标记，返回已用字节。代价 O(已用/4) 次比较，对 19 个任务
179	   * 每 500 ms 一次可以忽略；而它能把"栈打穿"这一整类原因（同样表现为永久卡住、
180	   * 信号无效、无法回收）从卡死现场直接排除掉。 */
181	  d->stack_size = (uint16_t)tcb->adj_stack_size;
182	  d->stack_used = (uint16_t)up_check_tcbstack(tcb, tcb->adj_stack_size);
183	#else
184	  d->stack_size = 0;
185	  d->stack_used = 0;
186	#endif
187	  schedmon_copy_name(d->name, tcb);
188	
189	  if (tcb->lockcount > s->lockmax)
190	    {
191	      s->lockmax = tcb->lockcount;
192	    }
193	
194	  if (tcb->task_state == TSTATE_WAIT_SEM)
195	    {
196	      s->n_wait_sem++;
197	    }
198	}
