210	bool myvendor_schedmon_snap_copy(struct myvendor_schedmon_snap_s *out)
211	{
212	  unsigned tries;
213	
214	  if (out == NULL)
215	    {
216	      return false;
217	    }
218	
219	  /* seqlock 读：写侧在 g_snap = tmp 期间把 gen 置为奇数，写完置为偶数。
220	   * 读 gen -> 拷贝 -> 再读 gen，两次相同才说明拷贝期间没被写打断。
221	   * 编译屏障防止编译器把 gen 的第二次读或结构体拷贝重排到屏障之外。
222	   * 不加锁、不开中断 —— 本函数要能在崩溃路径上跑。 */
223	  for (tries = 0; tries < MYVENDOR_SCHEDMON_SNAP_TRIES; tries++)
224	    {
225	      uint32_t g0 = g_snap.gen;
226	
227	      if ((g0 & 1u) != 0u)
228	        {
229	          continue; /* 正在写 */
230	        }
231	
232	      *out = g_snap;
233	      __asm__ volatile ("" ::: "memory");
234	      if (g_snap.gen == g0)
235	        {
236	          return true;
237	        }
238	    }
239	
240	  return false;
241	}
