243	void myvendor_schedmon_tick(void)
244	{
245	  struct myvendor_schedmon_snap_s tmp;
246	  irqstate_t flags;
247	  clock_t now = clock_systime_ticks();
248	  uint32_t null_n;
249	  uint32_t mutex_n;
250	  bool due;
251	  bool new_null;
252	  bool new_mutex;
253	
254	  memset(&tmp, 0, sizeof(tmp));
255	  tmp.ticks = (uint32_t)now;
256	  nxsched_foreach(schedmon_one, &tmp);
257	
258	  flags = up_irq_save();
259	  tmp.gen = g_snap.gen + 1u;
260	  tmp.null_n = g_null_n;
261	  tmp.mutex_bad_n = g_snap.mutex_bad_n;
262	  tmp.last_null = g_snap.last_null;
263	  tmp.last_mutex = g_snap.last_mutex;
264	  g_snap = tmp;
265	  g_snap.gen = tmp.gen + 1u;
266	  null_n = g_null_n;
267	  mutex_n = tmp.mutex_bad_n;
268	  up_irq_restore(flags);
269	
270	  new_null = (null_n != g_logged_null);
271	  new_mutex = (mutex_n != g_logged_mutex);
272	  due = (g_log_ticks == 0) ||
273	        ((clock_t)(now - g_log_ticks) >= SCHEDMON_TICKS_15S);
274	
275	  if (new_null)
276	    {
277	      const struct myvendor_schedmon_null_s *e = &g_snap.last_null;
278	
279	      if (null_n <= 4u || (null_n & 0xfu) == 0u)
280	        {
281	          syslog(LOG_ERR,
282	                 "sched: semnull n=%u err=%d irq=%lu "
283	                 "wt pid=%d %s st=%u pri=%d "
284	                 "run pid=%d %s st=%u lock=%d\n",
285	                 (unsigned)e->seq, (int)e->errcode,
286	                 (unsigned long)e->ipsr,
287	                 (int)e->wt_pid, e->wt_name, (unsigned)e->wt_state,
288	                 (int)e->wt_pri,
289	                 (int)e->run_pid, e->run_name, (unsigned)e->run_state,
290	                 (int)e->run_lock);
291	        }
292	
293	      g_logged_null = null_n;
294	    }
295	
296	  if (new_mutex)
297	    {
298	      const struct myvendor_schedmon_mutex_s *m = &g_snap.last_mutex;
299	
300	      if (mutex_n <= 4u || (mutex_n & 0xfu) == 0u)
301	        {
302	          syslog(LOG_ERR,
303	                 "sched: mutexbad n=%u holder=%ld tid=%d run=%d "
304	                 "this=%s st=%u run=%s st=%u\n",
305	                 (unsigned)m->seq, (long)m->holder,
306	                 (int)m->tid, (int)m->run_pid,
307	                 m->this_name, (unsigned)m->this_st,
308	                 m->run_name, (unsigned)m->run_st);
309	        }
310	
311	      g_logged_mutex = mutex_n;
312	    }
313	
314	  if (!due)
315	    {
316	      return;
317	    }
318	
319	  g_log_ticks = now;
320	#ifdef CONFIG_MYVENDOR_SCHEDMON_LOG
321	  /* 稳态汇总：健康时每 15 s 一模一样，20 行左右（含下面逐任务清单），会把监控
322	   * 环冲掉。默认不参与构建；卡死现场的同一份数据在崩溃转储的 snap 段里，要在
323	   * 控制台看趋势时再打开它。 */
324	  syslog(LOG_DEBUG,
325	         "sched: mon tasks=%u lockmax=%d waitsem=%u semnull=%u mutexbad=%u sembad=%u\n",
326	         (unsigned)g_snap.ntask, (int)g_snap.lockmax,
327	         (unsigned)g_snap.n_wait_sem, (unsigned)null_n,
328	         (unsigned)mutex_n, (unsigned)g_snap.sembad_n);
329	#endif
330	
331	  /* 诊断：waitobj 非空但计数/holder 不变量不成立。上游这里是 DEBUGASSERT，
332	   * 而 IRQ 上下文 assert 会递归、连核心转储都写不上（现场直接重启过），
333	   * 所以改成记录 + 继续。这条详情行给出当时的值和双方任务。 */
334	  if (g_snap.sembad_n != 0)
335	    {
336	      const struct myvendor_schedmon_null_s *b = &g_snap.last_sembad;
337	
338	      syslog(LOG_ERR,
339	             "sched: sembad n=%u irq=%lu bad_mutex=%u value=%ld err=%d wt pid=%d %s st=%u pri=%d run pid=%d %s st=%u lock=%d\n",
340	             (unsigned)b->seq, (unsigned long)b->ipsr,
341	             (unsigned)b->bad_mutex, (long)b->value, (int)b->errcode,
342	             (int)b->wt_pid, b->wt_name, (unsigned)b->wt_state,
343	             (int)b->wt_pri,
344	             (int)b->run_pid, b->run_name, (unsigned)b->run_state,
345	             (int)b->run_lock);
346	    }
347	
348	  /* 诊断：把最近一次 non-owner mutex post 的现场并进 15 s 汇总行。
349	   * 详情行只在计数变化时才打，过滤过的日志里经常看不到；非持有者解锁
350	   * 是未定义行为（可能留下卡死的 blocking 位），必须能直接定位到线程。 */
351	  if (mutex_n != 0)
352	    {
353	      const struct myvendor_schedmon_mutex_s *m = &g_snap.last_mutex;
354	
355	      syslog(LOG_ERR,
356	             "sched: mutexbad last n=%u holder=%ld tid=%d run=%d "
357	             "this=%s st=%u runner=%s st=%u sem=%p call=%p\n",
358	             (unsigned)m->seq, (long)m->holder, (int)m->tid, (int)m->run_pid,
359	             m->this_name, (unsigned)m->this_st,
360	             m->run_name, (unsigned)m->run_st,
361	             m->sem, m->caller);
362	    }
363	
364	#ifdef CONFIG_MYVENDOR_SCHEDMON_LOG
365	  for (unsigned i = 0; i < g_snap.ntask; i++)
366	    {
367	      const struct myvendor_schedmon_task_s *t = &g_snap.task[i];
368	      /* 只跳过"正常运行且没拿锁"的任务；**其余一律打印**。
369	       *
370	       * 这里原来是反过来的：`lockcount<=0 && state != TASK_WAIT_SEM &&
371	       * waitobj==0 && waitdog==0` 就 `continue`。那条过滤恰好把现场最要命的
372	       * 一类状态藏了起来 —— 一个"没有等任何东西、也没有看门狗在跑，却又不
373	       * 运行"的线程（GNSS 读线程卡死时就是它：日志里 tasks=19 只打 16 行，
374	       * 而 waitsem=10 与 10 条 st=5 完全吻合，说明卡住的线程不在其中）。
375	       *
376	       * 卡死于"某次 poll 里的等待"时 waitdog 必为 1；而现场是 waitdog==0、
377	       * waitobj==0 —— 那要么是 TCB 根本没跑起来（PENDING/INACTIVE，
378	       * 于是 phase 字符串是上一代的陈旧值、pid 也不会被写），要么是卡在
379	       * 驱动层自旋（RUNNING 却不在等信号量）。这两种只需 state 一个字段就能
380	       * 分开，所以必须把它打出来。 */
381	      if ((t->state == TSTATE_TASK_READYTORUN ||
382	           t->state == TSTATE_TASK_RUNNING) && t->lockcount <= 0)
383	        {
384	          continue;
385	        }
386	
387	      syslog(LOG_DEBUG,
388	             "sched: task pid=%d %s pri=%d st=%u err=%d lock=%d wait=%p wd=%u stk=%u/%u\n",
389	             (int)t->pid, t->name, (int)t->pri, (unsigned)t->state,
390	             (int)t->errcode, (int)t->lockcount, (void *)t->waitobj,
391	             (unsigned)t->waitdog, (unsigned)t->stack_used,
392	             (unsigned)t->stack_size);
393	    }
394	#endif /* CONFIG_MYVENDOR_SCHEDMON_LOG */
395	}
