441	static void note_board_snap(size_t *off)
442	{
443	  /* 崩溃路径：快照结构体几百字节，不能放栈上。 */
444	  static struct myvendor_schedmon_snap_s ls;
445	  const struct myvendor_schedmon_snap_s *s = &ls;
446	  const struct myvendor_schedmon_null_s *e;
447	  bool ok;
448	  unsigned i;
449	  int n;
450	
451	  /* 原来直接拿 myvendor_schedmon_snap() 的指针裸读，写侧虽然是 seqlock
452	   * （写时 gen 奇数）却没人校验 —— note 里可能混进两个 tick 的数据。
453	   * 这里改为拷贝 + 校验；拿不到一致副本就清零，宁可全 0 也不要假数据。 */
454	  ok = myvendor_schedmon_snap_copy(&ls);
455	  if (!ok)
456	    {
457	      memset(&ls, 0, sizeof(ls));
458	    }
459	
460	  note_append(off, "schedmon copy_ok=%d\n", ok ? 1 : 0);
461	  note_append(off,
462	              "schedmon tasks=%u lockmax=%d waitsem=%u semnull=%u "
463	              "mutexbad=%u gen=%u\n",
464	              (unsigned)s->ntask, (int)s->lockmax,
465	              (unsigned)s->n_wait_sem, (unsigned)s->null_n,
466	              (unsigned)s->mutex_bad_n, (unsigned)s->gen);
467	
468	  if (s->null_n != 0)
469	    {
470	      e = &s->last_null;
471	      note_append(off,
472	                  "semnull n=%u err=%d irq=%lu "
473	                  "wt pid=%d %s st=%u pri=%d "
474	                  "run pid=%d %s st=%u lock=%d\n",
475	                  (unsigned)e->seq, (int)e->errcode,
476	                  (unsigned long)e->ipsr,
477	                  (int)e->wt_pid, e->wt_name, (unsigned)e->wt_state,
478	                  (int)e->wt_pri,
479	                  (int)e->run_pid, e->run_name, (unsigned)e->run_state,
480	                  (int)e->run_lock);
481	    }
482	
483	  if (s->mutex_bad_n != 0)
484	    {
485	      const struct myvendor_schedmon_mutex_s *m = &s->last_mutex;
486	
487	      note_append(off,
488	                  "mutexbad n=%u holder=%ld tid=%d run=%d "
489	                  "this=%s st=%u run=%s st=%u\n",
490	                  (unsigned)m->seq, (long)m->holder,
491	                  (int)m->tid, (int)m->run_pid,
492	                  m->this_name, (unsigned)m->this_st,
493	                  m->run_name, (unsigned)m->run_st);
494	    }
495	
496	  for (i = 0; i < s->ntask; i++)
497	    {
498	      const struct myvendor_schedmon_task_s *t = &s->task[i];
499	
500	      /* stk=已用/总大小：栈打穿会表现成"内存被人写坏"的样子（现场 val 是垃圾、
501	       * 相关结构莫名错位），必须能从转储里一眼排除，否则每次都要回头查一遍。
502	       * 这两个字段快照里早就有（见 myvendor_schedmon_task_s），只是这里漏打了，
503	       * 于是 console 上的 `sched: task … stk=` 有水位、崩溃转储里反而没有。 */
504	      note_append(off,
505	                  "snap pid=%d %s pri=%d st=%u lock=%d wait=%p wd=%u stk=%u/%u\n",
506	                  (int)t->pid, t->name, (int)t->pri, (unsigned)t->state,
507	                  (int)t->lockcount, (void *)t->waitobj,
508	                  (unsigned)t->waitdog, (unsigned)t->stack_used,
509	                  (unsigned)t->stack_size);
510	    }
511	
512	  n = myvendor_gnss_crash_format(g_fmt, sizeof(g_fmt));
513	  if (n > 0)
514	    {
515	      note_append(off, "%s\n", g_fmt);
516	    }
517	
518	  n = myvendor_sound_crash_format(g_fmt, sizeof(g_fmt));
519	  if (n > 0)
520	    {
521	      note_append(off, "%s\n", g_fmt);
522	    }
523	}
