1154	static void coredump_write_assert(uintptr_t sp, FAR struct tcb_s *tcb,
1155	                                  FAR const char *filename, int lineno,
1156	                                  FAR const char *msg, FAR void *regs)
1157	{
1158	  size_t off = 0;
1159	  FAR uint32_t *assert_regs = (FAR uint32_t *)regs;
1160	  FAR uint32_t *fault_regs = NULL;
1161	
1162	  if (g_busy)
1163	    {
1164	      return;
1165	    }
1166	
1167	  g_busy = true;
1168	  myvendor_watchdog_keepalive_once();
1169	  crash_claim_fb();
1170	  memset(g_note, 0, g_note_cap);
1171	  coredump_fill_common(&off, "assert");
1172	  note_append(&off, "wdt_pet=1\n");
1173	
1174	  note_append(&off, "file=%s\n", filename != NULL ? filename : "?");
1175	  note_append(&off, "line=%d\n", lineno);
1176	  note_append(&off, "msg=%s\n", msg != NULL ? msg : "");
1177	  note_append(&off, "irq=%d\n", up_interrupt_context() ? 1 : 0);
1178	  note_append(&off, "sp=0x%lx\n", (unsigned long)sp);
1179	
1180	  if (tcb != NULL)
1181	    {
1182	      note_append(&off, "pid=%d name=%s pri=%d st=%u lock=%d wait=%p\n",
1183	                  (int)tcb->pid, get_task_name(tcb),
1184	                  (int)tcb->sched_priority,
1185	                  (unsigned)tcb->task_state, (int)tcb->lockcount,
1186	                  tcb->waitobj);
1187	    }
1188	
1189	  snprintf(g_fmt, sizeof(g_fmt),
1190	           "\n[coredump] assert %s:%d irq=%d writing kv\n",
1191	           filename != NULL ? filename : "?", lineno,
1192	           up_interrupt_context() ? 1 : 0);
1193	  coredump_puts_line(g_fmt);
1194	
1195	  if (up_interrupt_context())
1196	    {
1197	      fault_regs = (FAR uint32_t *)running_regs();
1198	    }
1199	  else if (tcb != NULL)
1200	    {
1201	      fault_regs = tcb->xcp.regs;
1202	    }
1203	
1204	  if (fault_regs == NULL)
1205	    {
1206	      fault_regs = assert_regs;
1207	    }
1208	
1209	  note_hw_cpu(&off);
1210	  note_scb_fault(&off);
1211	
1212	  note_append(&off, "fault_regs\n");
1213	  note_arm_regs(&off, fault_regs);
1214	
1215	  if (assert_regs != NULL && assert_regs != fault_regs)
1216	    {
1217	      note_append(&off, "assert_regs\n");
1218	      note_arm_regs(&off, assert_regs);
1219	    }
1220	
1221	  note_board_snap(&off);
1222	
1223	  if (!up_interrupt_context())
1224	    {
1225	      nxsched_foreach(note_one_task, &off);
1226	    }
1227	  else
1228	    {
1229	      note_append(&off, "tasks=schedmon (irq, skip foreach)\n");
1230	    }
1231	
1232	  coredump_enter_baremetal(off);
1233	}
