83	static inline_function
84	int get_blocking(FAR sem_t *sem, bool mutex, bool *blocking)
85	{
86	  int32_t mholder = NXSEM_NO_MHOLDER;
87	  int ret = OK;
88	
89	  if (mutex)
90	    {
91	      pid_t tid;
92	      pid_t run_pid;
93	      int32_t holder;
94	
95	      /* Mutex post from interrupt context is not allowed */
96	
97	      DEBUGASSERT(!up_interrupt_context());
98	
99	      /* Lock the mutex for us by setting the blocking bit */
100	
101	      mholder = atomic_or(NXSEM_MHOLDER(sem), NXSEM_MBLOCKING_BIT);
102	      holder = mholder & (~NXSEM_MBLOCKING_BIT);
103	      tid = mutex_post_tid();
104	      run_pid = (g_running_task != NULL) ? g_running_task->pid : tid;
105	
106	      /* 上游 DEBUGASSERT holder==tid。gettid 不可靠时用 running_task 再比一次。 */
107	
108	      if (mholder != (NXSEM_MBLOCKING_BIT | NXSEM_NO_MHOLDER) &&
109	          holder != (int32_t)tid &&
110	          holder != (int32_t)run_pid)
111	        {
112	          /* 连**是哪把锁、从哪一行**一起记下来。
113	           *
114	           * 只有 holder/tid/线程名的话，这份记录只能说明"某个线程释放了一个它
115	           * 不持有的互斥量"，无法定位 —— 而这类 UB 的后果（blocking 位残留 →
116	           * 之后任何等它的线程永久阻塞）必须知道是哪把锁才能修。
117	           * `sem` 让同一把锁的多次误用归并到一起；`caller` 用
118	           * `arm-none-eabi-addr2line -e nuttx <addr>` 就能标出调用点。 */
119	          myvendor_schedmon_mutex_bad(mholder, tid, run_pid, sem,
120	                                      __builtin_return_address(0));
121	
122	          /* **顺手把已经写坏的 holder 修回来。**
123	           *
124	           * 现场看到的值是 `NXSEM_NO_MHOLDER - 2`（0x7FFFFFFD）—— 也就是有人
125	           * 对互斥量做了**计数语义的减法**。这种值不可能是"我们认错的持有者"，
126	           * 而是字段真的坏了。
127	           *
128	           * 为什么必须修：下面那句 `if (!*blocking) atomic_set(NO_MHOLDER)` 只在
129	           * **没有** blocking 位时才清；而现场 blocking 位是立着的 → 残留下来 →
130	           * **之后任何等这把锁的线程会永久阻塞**（正是异常1 里 companion 卡在
131	           * `nxmutex_wait` 的形态）。这是"埋着的雷"。
132	           *
133	           * 判据故意收得很窄：只有 holder **大于任何合法 pid**（本系统 pid 上限
134	           * 32767）才动手。这样绝不会误清一个真的被持有的锁 —— 而 `tid` 判据本身
135	           * 可能不可靠（见上面注释），所以不能拿"判据成立"当清锁的理由。 */
136	          if (holder > 32767)
137	            {
138	              atomic_set(NXSEM_MHOLDER(sem), NXSEM_NO_MHOLDER);
139	            }
140	        }
141	
142	      *blocking = NXSEM_MBLOCKING(mholder);
143	
144	      if (!(*blocking))
145	        {
146	          atomic_set(NXSEM_MHOLDER(sem), NXSEM_NO_MHOLDER);
147	        }
148	    }
149	  else
150	    {
151	      int32_t sem_count;
152	
153	      /* Check the maximum allowable value */
154	
155	      sem_count = atomic_read(NXSEM_COUNT(sem));
156	      do
157	        {
158	          if (sem_count >= SEM_VALUE_MAX)
159	            {
160	              ret = -EOVERFLOW;
161	              break;
162	            }
163	        }
164	      while (!atomic_try_cmpxchg_release(NXSEM_COUNT(sem), &sem_count,
165	                                         sem_count + 1));
166	      *blocking = sem_count < 0;
167	    }
168	
169	  return ret;
170	}
