176	int nxsem_post_slow(FAR sem_t *sem)
177	{
178	  FAR struct tcb_s *stcb = NULL;
179	  irqstate_t flags;
180	#if defined(CONFIG_PRIORITY_INHERITANCE) || defined(CONFIG_PRIORITY_PROTECT)
181	  uint8_t proto;
182	#endif
183	  bool blocking = false;
184	  bool mutex = NXSEM_IS_MUTEX(sem);
185	  int ret = OK;
186	
187	  flags = enter_critical_section();
188	
189	  ret = get_blocking(sem, mutex, &blocking);
190	
191	  if (ret == OK)
192	    {
193	      if (!mutex || blocking)
194	        {
195	          nxsem_release_holder(sem);
196	        }
197	
198	#if defined(CONFIG_PRIORITY_INHERITANCE) || defined(CONFIG_PRIORITY_PROTECT)
199	      proto = sem->flags & SEM_PRIO_MASK;
200	      if (proto != SEM_PRIO_NONE)
201	        {
202	          sched_lock();
203	        }
204	#endif
205	
206	      if (blocking)
207	        {
208	          stcb = (FAR struct tcb_s *)dq_remfirst(SEM_WAITLIST(sem));
209	          if (stcb != NULL)
210	            {
211	              FAR struct tcb_s *rtcb = this_task();
212	
213	              if (mutex)
214	                {
215	                  int32_t blocking_bit = dq_empty(SEM_WAITLIST(sem)) ?
216	                    0 : NXSEM_MBLOCKING_BIT;
217	                  atomic_set(NXSEM_MHOLDER(sem), stcb->pid | blocking_bit);
218	                }
219	              else
220	                {
221	                  nxsem_add_holder_tcb(stcb, sem);
222	                }
223	
224	              wd_cancel(&stcb->waitdog);
225	              stcb->waitobj = NULL;
226	
227	              if (nxsched_add_readytorun(stcb))
228	                {
229	                  nxsched_switch(this_task(), rtcb);
230	                }
231	            }
232	        }
233	
234	#if defined(CONFIG_PRIORITY_INHERITANCE) || defined(CONFIG_PRIORITY_PROTECT)
235	      if (proto != SEM_PRIO_NONE)
236	        {
237	          if (proto == SEM_PRIO_INHERIT)
238	            {
239	#  ifdef CONFIG_PRIORITY_INHERITANCE
240	              nxsem_restore_baseprio(stcb, sem);
241	#  endif
242	            }
243	          else if (proto == SEM_PRIO_PROTECT)
244	            {
245	#  ifdef CONFIG_PRIORITY_PROTECT
246	              nxsem_protect_post(sem);
247	#  endif
248	            }
249	
250	          sched_unlock();
251	        }
252	#endif
253	    }
254	
255	  leave_critical_section(flags);
256	
257	  return ret;
258	}
